import{_ as e,o as l,c as r,a2 as t}from"./chunks/framework.z3u3TMv0.js";const h=JSON.parse('{"title":"安裝 llama.cpp","description":"使用 llama.cpp / llama-server 加載 GGUF，為 MiniTavern 提供 OpenAI 兼容接口。","frontmatter":{"title":"安裝 llama.cpp","description":"使用 llama.cpp / llama-server 加載 GGUF，為 MiniTavern 提供 OpenAI 兼容接口。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 llama.cpp · MiniTavern Docs"}],["meta",{"property":"og:description","content":"使用 llama.cpp / llama-server 加載 GGUF，為 MiniTavern 提供 OpenAI 兼容接口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/llamacpp/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/llamacpp/install"}]]},"headers":[],"relativePath":"zh-TW/llamacpp/install.md","filePath":"zh-TW/llamacpp/install.md","lastUpdated":1787224147000}'),i={name:"zh-TW/llamacpp/install.md"};function n(o,a,p,s,c,m){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="安裝與上手-llama-cpp" tabindex="-1">安裝與上手（llama.cpp） <a class="header-anchor" href="#安裝與上手-llama-cpp" aria-label="Permalink to &quot;安裝與上手（llama.cpp）&quot;">​</a></h1><p><a href="https://github.com/ggerganov/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> 提供高性能 GGUF 推理；其中的 <strong><code>llama-server</code></strong>（或發行版中的 server 二進制）可暴露 HTTP API，供 MiniTavern 使用。</p><p>適合：已經會下 GGUF、希望依賴少、參數可控的用戶。新手若只想點選下載，可先看 <a href="/ultra_guides/zh-TW/lmstudio/install">LM Studio</a> 或 <a href="/ultra_guides/zh-TW/ollama/install">Ollama</a>。</p><h2 id="獲取" tabindex="-1">獲取 <a class="header-anchor" href="#獲取" aria-label="Permalink to &quot;獲取&quot;">​</a></h2><ol><li>從官方倉庫 Releases 下載預編譯包，或按文檔自行編譯（CUDA / Metal / Vulkan）。</li><li>確認包內有 <strong>server</strong> 相關可執行文件（名稱可能為 <code>llama-server</code>、<code>server</code> 等，以你下載的版本為準）。</li><li>準備 GGUF 模型，見 <a href="/ultra_guides/zh-TW/local/models">推薦模型</a>。</li></ol><h2 id="快速驗證" tabindex="-1">快速驗證 <a class="header-anchor" href="#快速驗證" aria-label="Permalink to &quot;快速驗證&quot;">​</a></h2><p>在模型能本機推理後，再開啟 HTTP 服務（見下一頁）。先保證命令行加載模型無報錯。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./server">開啟 server</a> → <a href="/ultra_guides/zh-TW/connect-app/minitavern">在 MiniTavern 中配置</a></p>',9)])])}const u=e(i,[["render",n]]);export{h as __pageData,u as default};
